    """rejoin 审批单 message 必须逐字一致的紧凑 JSON（无空格、键序
    固定为 rejoin_id,dkg_id,round,node,key）。"""
    return json.dumps(
        {
            "rejoin_id": rejoin_id,
            "dkg_id": dkg_id,
            "round": round_no,
            "node": node,
            "key": key,
