        with self._wallet_lock(wallet_id):
            self._heal_wallet(wallet_id)
            self._get_wallet_or_404(wallet_id)
            self._assert_wallet_active_locked(wallet_id)
            if not isinstance(body, dict) or set(body) != {
                "cancel_id",
                "reason",
            }:
                raise ServiceError(
                    400,
                    "body must contain exactly cancel_id and reason",
                )
            cancel_id = body["cancel_id"]
            reason = body["reason"]
            if not isinstance(cancel_id, str) or not _SAFE_ID.match(
                cancel_id
            ):
                raise ServiceError(400, "invalid cancel_id")
            if not self._valid_request_cancel_reason(reason):
                raise ServiceError(
                    400,
                    "reason must be a non-blank string of 1 to "
                    f"{MAX_REASON_LENGTH} characters",
                )
            record = self._fetch_request_or_404(wallet_id, request_id)
            record = self._expire_if_needed(wallet_id, record)
            cancel_events = self._request_cancel_events_strict(wallet_id)
            existing = cancel_events.get(request_id)
            if existing is not None:
                if (
                    existing["actor_id"] == cancel_id
                    and existing["reason"] == reason
                ):
                    return 200, self._request_view(record)
                raise ServiceError(
                    409,
                    "signing request was cancelled with different parameters",
                )
            for event in cancel_events.values():

def _validate_approver_id(approver_id: object) -> None:
    if (
        not isinstance(approver_id, str)
        or isinstance(approver_id, bool)
        or not approver_id
        or not approver_id.strip()
    ):
        raise ServiceError(
            400, "approver_id must be a non-empty string"
        )

@staticmethod
def _validate_reason(reason: object) -> None:
    if reason is None:
        return
    if not isinstance(reason, str) or isinstance(reason, bool):
        raise ServiceError(400, "reason must be a string")
    if not reason.strip():
        raise ServiceError(400, "reason must be non-blank")
    if len(reason) > MAX_REASON_LENGTH:
        raise ServiceError(
            400, f"reason must be at most {MAX_REASON_LENGTH} characters"
        )

def _decide(
    self,
    wallet_id: str,
    request_id: str,
    approver_id: object,
    reason: object,
    action: str,
) -> dict:
    try:
        with self._wallet_lock(wallet_id):
            self._heal_wallet(wallet_id)
            # 404 优先于 400：存在性先于 approver/reason 参数校验
            self._get_wallet_or_404(wallet_id)
            self._assert_wallet_active_locked(wallet_id)
            self._validate_approver_id(approver_id)
            self._validate_reason(reason)
            record = self._fetch_request_or_404(wallet_id, request_id)
            # 懒过期可能在此原子记一次 E；过期后操作落入终态分支（409、不记 A/R）
            record = self._expire_if_needed(wallet_id, record)
            if record["state"] == "cancelled":
                raise ServiceError(
                    409,
                    f"signing request {request_id!r} is cancelled, "
                    "not pending",
                )
            roster = self._approval_roster_events_strict(wallet_id)
            # 同人同决定重放优先，返回 200、不计数、不复查当前名单：
            # 批准人已在审批单 approvers 中即同批准重放；拒绝重放由
            # request_rejected 事件的 actor_id 认定。
            if (
                action == "approve"
                and approver_id in record["approvers"]
            ):
                return self._request_view(record)
            if (
                action == "reject"
                and record["state"] == "rejected"
                and any(
                    event.get("request_id") == request_id
                    and event.get("actor_id") == approver_id
                    for event in self._audit.events_by_type(
                        wallet_id,
                        audit.TYPE_REQUEST_REJECTED,
                    )
                )
            ):
                return self._request_view(record)
            if record["state"] != "pending":
                raise ServiceError(
                    409,
                    f"signing request {request_id!r} is {record['state']}, "
                    "not pending",
                )
            if roster and approver_id not in roster:
                raise ServiceError(
                    409, "approver is not in the wallet approval roster"
                )

            if action == "approve":
                new_record = dict(record)
                new_record["approvers"] = list(record["approvers"])
                new_record["approvers"].append(approver_id)
                if reason is not None:
                    new_record["reason"] = reason
                reached = len(new_record["approvers"]) >= new_record["req"]
                if reached:
                    new_record["state"] = "approved"
                self._store.update_request(wallet_id, request_id, new_record)
                event = self._audit_event(
                    audit.TYPE_REQUEST_APPROVED,
                    request_id=request_id,
                    actor_id=approver_id,
                    reason=reason,
                    details={
                        "count": len(new_record["approvers"]),
                        "req": new_record["req"],
                        "state": new_record["state"],
                    },
                )
                try:
                    self._emit(wallet_id, event)
                except BaseException:
                    self._store.update_request(wallet_id, request_id, record)
                    raise
                return self._request_view(new_record)

            # reject：任何一名审批人拒绝即终态（首批）
            new_record = dict(record)
            new_record["state"] = "rejected"
            if reason is not None:
                new_record["reason"] = reason
            self._store.update_request(wallet_id, request_id, new_record)
            event = self._audit_event(
                audit.TYPE_REQUEST_REJECTED,
                request_id=request_id,
                actor_id=approver_id,
                reason=reason,
                details={
                    "count": len(new_record["approvers"]),
                    "req": new_record["req"],
                    "state": "rejected",
                },
            )
            try:
                self._emit(wallet_id, event)
            except BaseException:
                self._store.update_request(wallet_id, request_id, record)
                raise
            return self._request_view(new_record)
    except CorruptDataError:
        raise
    except ValueError:
        # wallet_id 含非法字符（构造锁路径时抛出）
        raise ServiceError(400, "invalid wallet_id")

def approve(
    self,
    wallet_id: str,
    request_id: str,
    approver_id: object,
    reason: object = None,
) -> dict:
    return self._decide(wallet_id, request_id, approver_id, reason, "approve")

def reject(
    self,
    wallet_id: str,
    request_id: str,
    approver_id: object,
    reason: object = None,
) -> dict:
    return self._decide(wallet_id, request_id, approver_id, reason, "reject")

# ---- 份额签名聚合 ---------------------------------------------------

def _signing_approval_gate(
    self, wallet_id: str, signing_request_id: str, message: str
) -> dict | None:
    """既有 /sign 与可恢复签名会话共用的审批 + 冷热门控。

    调用方须持有钱包事务锁。返回 approved 审批单记录（无审批要求时
    返回 None），门控不通过抛 ServiceError(409/404)。可能原子地把超时
    pending 单懒过期为 expired 并记一次 request_expired 事件。

    - cold 模式：首签必须存在同 id、同 message 且 approved 的审批单。
      未配置审批策略（无法建单）、无单或未 approved 一律 409；
    - hot（或未配交易策略）且配置了审批策略：沿用原审批规则
      （无单 404，message 不符/未 approved 409）；
    - 其余情形不要求审批单。
    """
    approval_record = None
    approval_policy = self._store.get_policy(wallet_id)
    transaction_policy = self._store.get_transaction_policy(wallet_id)
    cold_mode = (
        transaction_policy is not None
        and transaction_policy.get("mode") == "cold"
    )
    if cold_mode:
        try:
            approval_record = self._store.get_request(
                wallet_id, signing_request_id
            )
        except CorruptDataError:
            raise
        except ValueError:
            raise ServiceError(400, "invalid signing_request_id")
        if approval_record is None:
            raise ServiceError(
                409,
                f"cold wallet requires an approved signing request "
                f"{signing_request_id!r}",
            )
    elif approval_policy is not None:
        approval_record = self._fetch_request_or_404(
            wallet_id, signing_request_id
        )

def _normalize_adapters_body(self, adapters: object) -> dict:
    """校验 PUT chain-adapters 请求体 Q 的 adapters 表并归一。

    adapters 须为非空对象，键匹配 [A-Za-z0-9_-]{1,128}（dict 天然
    唯一）且**请求体内已按 ASCII 升序排列**（顺序错 400，不替客户端
    重排）；每值须为字符串 ``up|down``（拒绝布尔等非字符串）。返回按
    ASCII 升序的表（合法输入本就有序）。非法抛 ServiceError(400)。"""
    if not isinstance(adapters, dict) or not adapters:
        raise ServiceError(
            400,
            "adapters must be a non-empty object keyed by adapter id",
        )
    # 先确认键全为合法标识，再判定顺序与取值（混合类型键会让 sorted
    # 抛 TypeError，必须在排序前拦住，统一落 400 而非 503）。
    for adapter_id in adapters:
        if not isinstance(adapter_id, str) or not ROTATION_ID_RE.match(
            adapter_id
        ):
            raise ServiceError(
                400, "adapter id must match [A-Za-z0-9_-]{1,128}"
            )
    keys = list(adapters)
    if keys != sorted(keys):
        raise ServiceError(
            400, "adapters must be listed in ASCII ascending order"
        )
    normalized: dict[str, str] = {}
    for adapter_id in keys:
        state = adapters[adapter_id]
        if not isinstance(state, str) or state not in CHAIN_ADAPTER_STATES:
            raise ServiceError(
                400,
                "adapter state must be one of "
                + ", ".join(CHAIN_ADAPTER_STATES),
            )
        normalized[adapter_id] = state
    return normalized

def _chain_adapter_health_events_strict(
    self, wallet_id: str
) -> list[dict]:
    """返回该钱包全部 chain_adapter_health 事件（按 seq 升序）并逐条
    严格校验**形状**：

    - 外层七字段须为落盘规范序
      （actor_id,at,details,reason,request_id,seq,type）；
    - request_id/actor_id/reason 必须为 null；
    - details 恰含 ``adapters``（单键）；
    - adapters 非空、键为安全标识且按 ASCII **升序唯一**；
    - 每个值恰为字符串 ``up|down``。

    重排、形状或取值矛盾都是不可对账现场（RecoveryError）；审计 JSON
    损坏抛 CorruptDataError、文件 I/O 失败抛 OSError。纯只读，不分配
    seq。"""
    events = self._audit.events_by_type(
        wallet_id, audit.TYPE_CHAIN_ADAPTER_HEALTH
    )
    for event in events:
        if list(event) != list(_AUDIT_OUTER_KEY_ORDER):
            raise RecoveryError(
                f"wallet {wallet_id!r} has a chain_adapter_health event "
                "whose outer fields are out of the canonical order"
            )
        if (
            event.get("request_id") is not None
            or event.get("actor_id") is not None
            or event.get("reason") is not None
        ):
            raise RecoveryError(
                f"wallet {wallet_id!r} has a chain_adapter_health event "
                "with request_id/actor/reason set"
            )
        details = event.get("details")
        if not isinstance(details, dict) or list(details) != ["adapters"]:
            raise RecoveryError(
                f"wallet {wallet_id!r} has a malformed "
                "chain_adapter_health event"
            )
        adapters = details["adapters"]
        if not isinstance(adapters, dict) or not adapters:
            raise RecoveryError(
                f"wallet {wallet_id!r} has an empty or malformed "
                "chain_adapter_health adapters table"
            )
        # 排序前先确认键全为字符串（损坏现场可能含非字符串键）。
        if any(not isinstance(k, str) for k in adapters):
            raise RecoveryError(
                f"wallet {wallet_id!r} chain_adapter_health has a "
                "non-string adapter id"
            )
        keys = list(adapters)
        if keys != sorted(keys) or len(set(keys)) != len(keys):
            raise RecoveryError(
                f"wallet {wallet_id!r} chain_adapter_health adapters are "
                "not in strictly ascending order"
            )
        for adapter_id, state in adapters.items():
            if (
                not ROTATION_ID_RE.match(adapter_id)
                or not isinstance(state, str)
                or state not in CHAIN_ADAPTER_STATES
            ):
                raise RecoveryError(
                    f"wallet {wallet_id!r} chain_adapter_health has a "
                    f"malformed entry for adapter {adapter_id!r}"
                )
    return events

def _chain_adapters_locked(self, wallet_id: str) -> Optional[dict]:
    """当前适配器健康表（调用方须持钱包事务锁）：取最后一条
    chain_adapter_health 事件的归一表；从未配置返回 None。

    每条事件均经严格形状校验（矛盾抛 RecoveryError）。"""
    events = self._chain_adapter_health_events_strict(wallet_id)
    if not events:
        return None
    adapters = events[-1]["details"]["adapters"]
    return {key: adapters[key] for key in adapters}

def put_chain_adapters(self, wallet_id: str, adapters: object) -> dict:
    """设置跨链适配器健康熔断表，请求/成功响应（200）同为
    Q={"adapters": {A: "up"|"down"}}。

    adapters 非空、键匹配 [A-Za-z0-9_-]{1,128} 且请求体已按 ASCII
    升序排列，值仅 up|down；键集/类型/顺序/值错 400，钱包不存在 404，
    可首建。
    **首配/变更记一条 chain_adapter_health 事件；同值不记**
    （request_id/actor_id/reason 均为 null，details 恰为 Q）。健康表
    纯由审计事件持久化，不写状态文件。存在性判定、校验、比对与事件
    追加全部在每钱包跨进程事务锁内线性化：并发同参只有一个首配、其余
    同值不记。"""
    try:
        with self._wallet_lock(wallet_id):
            self._heal_wallet(wallet_id)
            # 404 优先于 400：锁内先判定钱包存在性，再校验请求体
            self._get_wallet_or_404(wallet_id)
            self._assert_wallet_active_locked(wallet_id)
            normalized = self._normalize_adapters_body(adapters)
            body = {"adapters": normalized}
            current = self._chain_adapters_locked(wallet_id)
            # 同值（归一后逐键相等）不记事件；首配或任何差异才记。
            if current != normalized:
                self._emit(
                    wallet_id,
                    self._audit_event(
                        audit.TYPE_CHAIN_ADAPTER_HEALTH,
                        details=body,
                    ),
                )
    except CorruptDataError:
        raise
    except ValueError:
        # wallet_id 含非法字符（构造锁路径时抛出）
        raise ServiceError(400, "invalid wallet_id")
    return body

def get_chain_adapters(self, wallet_id: str) -> dict:
    """读取跨链适配器健康表：已配置 200 返回 Q，从未配置 404。

    健康表纯由事件恢复（取最后一条）；损坏/矛盾事件 fail-closed（由
    HTTP 边界转 503）。钱包不存在 404。"""
    try:
        with self._wallet_lock(wallet_id):
            self._heal_wallet(wallet_id)
            # 404 优先：锁内先判定钱包存在，再判定健康表是否已配置
            self._get_wallet_or_404(wallet_id)
            adapters = self._chain_adapters_locked(wallet_id)
    except CorruptDataError:
        raise
    except ValueError:
        raise ServiceError(400, "invalid wallet_id")
    if adapters is None:
        raise ServiceError(
            404,
            f"wallet {wallet_id!r} has no configured chain adapter health",
        )
    return {"adapters": adapters}

def post_chain_report(
    self,

    仅当 details 键集恰为 R 六键时重排；畸形现场留给语义对账 fail-closed。
    其余提交事件的 details 维持原序（普通提交维持 sort_keys 序）。"""
    for index, event in enumerate(events):
        if not _reorg_compensation_commit(events, index):
            continue
        details = event.get("details")
        if isinstance(details, dict) and set(details) == set(
            _ASSET_OPERATION_R_KEY_ORDER
        ):
            event["details"] = {
                key: details[key] for key in _ASSET_OPERATION_R_KEY_ORDER
            }


def _canonical_event(
    event: object, preserve_details_order: bool = False
) -> object:
    """单条事件的落盘规范形：七字段 sort_keys，惟既定类型 details 保序。

    preserve_details_order 为真时，details 即使不在 _DETAILS_KEY_ORDER
    （重组补偿提交事件 asset_operation_committed）也按已归一的 R 键序原样
    保序，不随 sort_keys 重排。"""
    if not isinstance(event, dict):
        return _canonicalize_sorted(event)
    canonical = {}
    for key in sorted(event):
        value = event[key]
        if key == "details" and isinstance(value, dict) and (
            event.get("type") in _DETAILS_KEY_ORDER
            or preserve_details_order
        ):
            # 保留构造/读取时已归一为 README 既定顺序的 details 键序
            canonical[key] = value
        else:
            canonical[key] = _canonicalize_sorted(value)
    return canonical


def _canonical_log(data: dict) -> dict:
    """审计日志整体落盘规范形（顶层与各事件 sort_keys，既定 details 保序）。"""
    canonical = {}
    for key in sorted(data):
        value = data[key]
        if key == "events" and isinstance(value, list):
            # 重组补偿提交事件的 details 按 README 的 R 序落盘（不随
            # sort_keys 被重排为 state 先于 delta 的规范序）。
            _order_reorg_committed_details(value)
            canonical[key] = [
                _canonical_event(
                    event,
                    preserve_details_order=_reorg_compensation_commit(
                        value, index
                    ),
                )
                for index, event in enumerate(value)
            ]
        else:
            canonical[key] = _canonicalize_sorted(value)
    return canonical


def _atomic_write_log(path: str, data: dict) -> None:
    """与 WalletStore._atomic_write 相同的临时文件 + 原子替换；序列化按
    _canonical_log（既定事件类型的 details 按 README 既定键序落盘）。"""
    directory = os.path.dirname(path)
    os.makedirs(directory, exist_ok=True)
    fd, tmp_path = tempfile.mkstemp(dir=directory, prefix=".tmp-", suffix=".json")
    try:
        with os.fdopen(fd, "w", encoding="utf-8") as f:
            json.dump(_canonical_log(data), f, ensure_ascii=False, indent=2)
            f.write("\n")
        os.replace(tmp_path, path)
    except BaseException:
        try:
            os.unlink(tmp_path)
        except FileNotFoundError:
            pass
        raise


class AuditStore:
    """审计事件日志的仅追加文件存储（一个钱包一个文件）。"""

    def __init__(self, data_dir: str) -> None:
        self._data_dir = data_dir
        self._audit_dir = os.path.join(data_dir, "audit")
        self._lock = threading.Lock()

    def _path(self, wallet_id: str) -> str:
        _check_id("wallet_id", wallet_id)
        return os.path.join(self._audit_dir, wallet_id + ".json")

    @staticmethod
    def _event_shape_ok(event: object) -> bool:
        """单条审计事件的严格形状：

        seq 为非布尔正整数；type 为非空字符串；at 为可解析的 UTC 时间；
        request_id/actor_id/reason 为 null 或字符串；details 为对象。
        details 内部各事件类型的语义由相应恢复路径（轮换链/会话动作序列/
        账本对账）负责，全局加载不重复解释。"""
        if not isinstance(event, dict):
            return False
        seq = event.get("seq")
        if not isinstance(seq, int) or isinstance(seq, bool) or seq < 1:
            return False
        if not isinstance(event.get("type"), str) or not event["type"]:
            return False
        if parse_utc_iso(event.get("at")) is None:
            return False
        for key in ("request_id", "actor_id", "reason"):
            value = event.get(key)
            if value is not None and not isinstance(value, str):
                return False
        if not isinstance(event.get("details"), dict):
            return False
        return True

    def _read_strict(self, wallet_id: str) -> Optional[dict]:
        """读取并严格校验审计文件；文件不存在返回 None。

        以下现场一律视为不可对账的数据损坏（CorruptDataError），绝不静默
        归一为空日志后覆盖历史：JSON 不可解析、顶层不是对象、events 缺失
        或不是列表、wallet_id 字段不匹配、任一事件形状非法、seq 不从 1
        起 / 不连续 / 有重号、记录的 next_seq 与实际最大 seq 矛盾。
        """
        path = self._path(wallet_id)
        data = WalletStore._read_json(path)
        if data is None:
            return None
        if not isinstance(data, dict):
            raise CorruptDataError(
                f"audit log {path!r} top-level value is not an object"
            )
        recorded_wallet = data.get("wallet_id")
        if recorded_wallet is not None and recorded_wallet != wallet_id:
            raise CorruptDataError(
                f"audit log {path!r} wallet_id {recorded_wallet!r} does not "
                f"match its file name {wallet_id!r}"
            )
        events = data.get("events")
        if "events" not in data or not isinstance(events, list):
            raise CorruptDataError(
                f"audit log {path!r} has no list-valued 'events'"
            )
        seqs: list[int] = []
        for event in events:
            if not self._event_shape_ok(event):
                raise CorruptDataError(
                    f"audit log {path!r} has a malformed event"
                )
            seqs.append(event["seq"])
        # seq 必须恰为 1..N：不重号、不缺口、单调（物理顺序允许被外部重排，
        # 查询始终按 seq 升序；但 seq 集合本身必须连续）。
        if sorted(seqs) != list(range(1, len(seqs) + 1)):
            raise CorruptDataError(
                f"audit log {path!r} has a non-contiguous or duplicated seq"
            )
        stored_next = data.get("next_seq")
        if stored_next is not None:
            if (
                not isinstance(stored_next, int)
                or isinstance(stored_next, bool)
                or stored_next != len(events) + 1
            ):
                raise CorruptDataError(
                    f"audit log {path!r} next_seq disagrees with its events"
                )
        # 既定事件类型的 details 在内存视图中归一为 README 既定键序，
        # 使查询/重建/重写（落盘与灾备）都按该顺序保序。
        #
        # 但归一化会就地重排键序，必须**先**对落盘原序严格的类型核对其
        # 落盘 details 键序：错序即外部篡改/不可对账（RecoveryError），
        # 绝不先归一再校验而把错序静默抹平。审计 JSON 本身解析失败已在
        # WalletStore._read_json 处抛 CorruptDataError。
        for event in events:
            if event.get("type") in _STRICT_OUTER_ORDER_TYPES and list(
                event
            ) != list(_OUTER_KEY_ORDER):
                raise RecoveryError(
                    f"audit log {path!r} has a "
                    f"{event.get('type')} event whose outer fields are out "
                    "of the canonical order"
                )
            if (
                event.get("type") in _STRICT_DETAILS_ORDER_TYPES
                and not _stored_details_has_canonical_order(event)
            ):
                raise RecoveryError(
                    f"audit log {path!r} has a "
                    f"{event.get('type')} event whose details are out of "
                    "the canonical order"
                )
        # 重组补偿三事件批的收尾提交事件（seq-1 为同 request_id 的
        # chain_dispatch_reorged）的 asset_operation_committed.details 必须
        # 按 README 的 R 序落盘；错序即在归一化之前 fail-closed，绝不先
        # 归一而抹平重排。按 seq 邻接判定（物理顺序允许被外部重排）。
        by_seq = {event["seq"]: event for event in events}
        for event in events:
            if event.get("type") != TYPE_ASSET_OPERATION_COMMITTED:
                continue
            predecessor = by_seq.get(event["seq"] - 1)
            if not (
                isinstance(predecessor, dict)
                and predecessor.get("type") == TYPE_CHAIN_DISPATCH_REORGED
                and predecessor.get("request_id") is not None
                and predecessor.get("request_id") == event.get("request_id")
            ):
                continue
            details = event.get("details")
            if (
                not isinstance(details, dict)
                or list(details) != list(_ASSET_OPERATION_R_KEY_ORDER)
            ):
                raise RecoveryError(
                    f"audit log {path!r} has an "
                    "asset_operation_committed event for a reorg "
                    "compensation whose details are out of the R order"
                )
        for event in events:
            _order_event_details(event)
        # 重组补偿提交事件的 details 在内存视图中同样归一为 R 序（落盘与
        # 恢复一致）；普通提交事件维持既有 sort_keys 序不变。
        _order_reorg_committed_details(events)
        # 防篡改摘要链：按读取归一化后的事件（七字段含 details，键升序
        # 紧凑 JSON）重算链头，与顶层 chain 对象对账。旧记录可能缺链
        # （只读路径容忍，由追加/备份持锁补算，不改写事件正文）；链一旦
        # 存在，任何元数据形状或摘要矛盾都 fail-closed（RecoveryError），
        # 绝不覆盖现场。
        try:
            count, head = compute_chain_head(events)
        except (TypeError, KeyError, ValueError) as exc:
            raise RecoveryError(
                f"audit log {path!r} has an event that cannot be hashed "
                f"into the chain: {exc}"
            ) from exc
        if "chain" in data:
            _validate_stored_chain(path, data.get("chain"), count, head)
