      reason=null、details 四键固定序、target 受控）由
      :meth:`_change_control_events_strict` 严格校验；
    - before/after 按 target 为 null（仅 before 允许）或合法配置；
    - before 恰为按 seq 前缀折叠出的事前配置（未配置为 null）；
    - 同钱包审批单存在、message 逐字为仅含
      change_id,target,before,after 的 ASCII 紧凑 JSON、状态为
      approved（其后推进为 signed 亦认可）且有两位不同审批人；
    - 事件型配置（roster/dkg 开关/nodes/adapters）的提交事件必须与
      紧邻的前一条同 target 既有类型快照事件成对（同批原子），且
      快照即 after；文件型/change-control 目标前一条不得是夹带的
      同类快照。

    任一矛盾都是不可对账现场（RecoveryError，fail-closed，保留
    现场）；审计 JSON 损坏抛 CorruptDataError、I/O 失败抛 OSError。
    纯只读，不记事件、不改 seq、不写状态。"""
    events = self._change_control_events_strict(wallet_id)
    if not events:
        return
    all_events = self._audit.all_events(wallet_id)
    by_seq = {event["seq"]: event for event in all_events}
    # 各目标按 seq 前缀折叠的事前配置（仅维护事件型/开关时间线；
    # 文件型配置按存储文件与 before 复核，见下）。
    snapshot_targets = {
        "approval-roster",
        "dkg-failover-policy",
        "nodes",
        "chain-adapters",
        "change-control",
    }
    current: dict[str, object] = {
        "approval-roster": {"allowed_approvers": []},
        "dkg-failover-policy": {"enabled": False},
        "nodes": None,
        "chain-adapters": None,
        "change-control": {"enabled": False},
    }
    snapshot_type = {
        "approval-roster": audit.TYPE_APPROVAL_ROSTER_UPDATED,
        "dkg-failover-policy": audit.TYPE_DKG_FAILOVER_POLICY_UPDATED,
        "nodes": audit.TYPE_NODE_STATE,
        "chain-adapters": audit.TYPE_CHAIN_ADAPTER_HEALTH,
    }
    for event in events:
        seq = event["seq"]
        change_id = event["request_id"]
        approval_request_id = event["actor_id"]
        target = event["details"]["target"]
        before = event["details"]["before"]
        after = event["details"]["after"]

        # before/after 形状按 target 严格校验。
        if target == "approval-policy" or target == "transaction-policy":
            if before is not None:
                self._recover_config_shape(wallet_id, target, before)
            self._recover_config_shape(wallet_id, target, after)
        else:
            if before is not None:
                self._recover_config_shape(wallet_id, target, before)
            self._recover_config_shape(wallet_id, target, after)

        # 事前配置核对。
        if target in snapshot_targets:
            if current[target] != before:
                raise RecoveryError(
                    f"wallet {wallet_id!r} policy_change_applied "
                    f"{change_id!r} before does not match the preceding "
                    "configuration"
                )
        else:
            # 文件型配置：事件只追加不删除，故 before 必非 null
            # （首建只能经原 PUT；统一入口不产生 null before 的文件
            # 配置事件），且与其后所有同目标事件折叠值一致——直接
            # 核对存储文件当前值等于最后一条 after。
            if before is None:
                raise RecoveryError(
                    f"wallet {wallet_id!r} policy_change_applied "
                    f"{change_id!r} creates a file-backed config with a "
                    "null before"
                )

        # 事件型配置须与紧邻前一条同类型快照事件成对。
        if target in snapshot_type:
            predecessor = by_seq.get(seq - 1)
            if (
                not isinstance(predecessor, dict)
                or predecessor.get("type") != snapshot_type[target]
            ):
                raise RecoveryError(
                    f"wallet {wallet_id!r} policy_change_applied "
                    f"{change_id!r} is missing its paired config snapshot"
                )
            self._assert_snapshot_matches(
                wallet_id, target, predecessor, after, change_id
            )
        else:
            # 文件型/change-control：紧邻前一条不得是夹带的受控快照
            # （change-control 无快照；approval-policy/transaction
            # 走 policy_updated/transaction_policy_updated 旧事件）。
            predecessor = by_seq.get(seq - 1)
            if isinstance(predecessor, dict) and predecessor.get(
                "type"
            ) in (
                audit.TYPE_APPROVAL_ROSTER_UPDATED,
                audit.TYPE_DKG_FAILOVER_POLICY_UPDATED,
                audit.TYPE_NODE_STATE,
                audit.TYPE_CHAIN_ADAPTER_HEALTH,
            ):
                raise RecoveryError(
                    f"wallet {wallet_id!r} policy_change_applied "
                    f"{change_id!r} has an unpaired config snapshot"
                )

        # 审批单复核：存在、message 逐字一致、approved（signed 亦可）、
        # 两位不同审批人。
        approval = self._store.get_request(
            wallet_id, approval_request_id
        )
        if not isinstance(approval, dict):
            raise RecoveryError(
                f"wallet {wallet_id!r} policy_change_applied "
                f"{change_id!r} refers to an unknown approval request"
            )
        expected_message = self._policy_change_approval_message(
            change_id, target, before, after
        )
        if approval.get("message") != expected_message:
            raise RecoveryError(
                f"wallet {wallet_id!r} policy_change_applied "
                f"{change_id!r} approval message does not match"
            )
        if approval.get("state") not in ("approved", "signed"):
            raise RecoveryError(
                f"wallet {wallet_id!r} policy_change_applied "
                f"{change_id!r} approval request is not approved"
            )
        approvers = approval.get("approvers")
        if (
            not isinstance(approvers, list)
            or len(approvers) < 2
            or len(set(approvers)) < 2
        ):
            raise RecoveryError(
                f"wallet {wallet_id!r} policy_change_applied "
                f"{change_id!r} requires two distinct approvers"
            )

        # 折叠时间线前进一步。
        if target in snapshot_targets:
            current[target] = after

    # 文件型配置：当前存储值必须等于该目标最后一条 after。
    for target in ("approval-policy", "transaction-policy"):
        file_events = [
            event
            for event in events
            if event["details"]["target"] == target
        ]
        if not file_events:
            continue
        last_after = file_events[-1]["details"]["after"]
        current_view = self._controlled_config_view_locked(
            wallet_id, target
        )
        if current_view != last_after:
            raise RecoveryError(
                f"wallet {wallet_id!r} {target} file does not match its "
                "last policy_change_applied after"
            )

def _recover_config_shape(
    self, wallet_id: str, target: str, value: object
) -> None:
    """恢复路径上的配置形状校验：形状/取值非法即 RecoveryError
    （fail-closed），区别于在线请求的 ServiceError(400)。

    复用在线归一逻辑，但把 400 一律视为不可对账矛盾。"""
    try:
        self._validate_policy_change_config(wallet_id, target, value)
    except ServiceError as exc:
        raise RecoveryError(
            f"wallet {wallet_id!r} has a malformed policy_change_applied "
            f"config for {target}: {exc.message}"
        ) from exc

def _assert_snapshot_matches(
    self,
    wallet_id: str,
    target: str,
    snapshot_event: dict,
    after: object,
    change_id: str,
) -> None:
    """核对与提交事件同批的配置快照事件内容恰为 after。"""
    details = snapshot_event.get("details")
    if target == "approval-roster":
        expected = {
            "allowed_approvers": list(after["allowed_approvers"])
        }
    elif target == "dkg-failover-policy":
        expected = {"enabled": after["enabled"]}
    elif target == "nodes":
        expected = {"nodes": after["nodes"]}
    else:
        expected = {"adapters": after["adapters"]}
    if details != expected:
        raise RecoveryError(
            f"wallet {wallet_id!r} policy_change_applied {change_id!r} "
            "paired config snapshot does not match its after"
        )
    if (
        snapshot_event.get("request_id") is not None
        or snapshot_event.get("actor_id") is not None
        or snapshot_event.get("reason") is not None
    ):
        raise RecoveryError(
            f"wallet {wallet_id!r} policy_change_applied {change_id!r} "
            "paired config snapshot carries request/actor/reason"
        )

def _assert_change_control_allows_locked(
    self, wallet_id: str, target: str
) -> None:
    """开关启用后，受控目标的原 PUT 一律 409（调用方须持钱包事务
    锁，且已通过钱包存在性/冻结闸门）：零副作用，由 HTTP 层在读取
    请求体之前判定。"""
    if self._change_control_enabled_locked(wallet_id):
        raise ServiceError(409, "change control required")

