# -- 恢复对账 ---------------------------------------------------------

#: 事件型受控目标 -> 其既有类型快照事件
_CHANGE_SNAPSHOT_TYPES = {
    "approval-roster": audit.TYPE_APPROVAL_ROSTER_UPDATED,
    "dkg-failover-policy": audit.TYPE_DKG_FAILOVER_POLICY_UPDATED,
    "nodes": audit.TYPE_NODE_STATE,
